-- Generated by scripts/build_schema.py; change db/catalog.py.
BEGIN;

CREATE TABLE dataset_run (
  run_id text PRIMARY KEY CHECK (run_id ~ '^RUN-[0-9]{8}-[a-z0-9]+$') CHECK (length(trim(run_id)) > 0),
  seed bigint NOT NULL CHECK (seed >= 0),
  profile text NOT NULL CHECK (profile IN ('starter', 'full', 'custom')) CHECK (length(trim(profile)) > 0),
  start_at timestamptz NOT NULL,
  cutoff_at timestamptz NOT NULL,
  policy_version text NOT NULL CHECK (length(trim(policy_version)) > 0),
  config_sha256 text NOT NULL CHECK (config_sha256 ~ '^[a-f0-9]{64}$') CHECK (length(trim(config_sha256)) > 0),
  CHECK (start_at < cutoff_at)
);

CREATE TABLE customer (
  customer_id text PRIMARY KEY CHECK (customer_id ~ '^CUS-[0-9]{6,}$') CHECK (length(trim(customer_id)) > 0),
  run_id text NOT NULL REFERENCES dataset_run(run_id) ON DELETE RESTRICT CHECK (length(trim(run_id)) > 0),
  email text UNIQUE CHECK (length(trim(email)) > 0),
  phone_token text UNIQUE CHECK (length(trim(phone_token)) > 0),
  timezone text NOT NULL CHECK (length(trim(timezone)) > 0),
  created_at timestamptz NOT NULL,
  CHECK (email IS NULL OR email LIKE '%@example.test')
);

CREATE TABLE consent (
  consent_id text PRIMARY KEY CHECK (consent_id ~ '^CON-[0-9]{6,}$') CHECK (length(trim(consent_id)) > 0),
  customer_id text NOT NULL REFERENCES customer(customer_id) ON DELETE RESTRICT CHECK (length(trim(customer_id)) > 0),
  channel text NOT NULL CHECK (channel IN ('email', 'sms')) CHECK (length(trim(channel)) > 0),
  state text NOT NULL CHECK (state IN ('granted', 'withdrawn')) CHECK (length(trim(state)) > 0),
  effective_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL,
  revision bigint NOT NULL CHECK (revision >= 1),
  source text NOT NULL CHECK (source IN ('checkout', 'preference_center', 'support', 'synthetic')) CHECK (length(trim(source)) > 0),
  UNIQUE (customer_id, channel, revision)
);

CREATE TABLE session (
  session_id text PRIMARY KEY CHECK (session_id ~ '^SES-2026-[0-9]{6,}$') CHECK (length(trim(session_id)) > 0),
  customer_id text NOT NULL REFERENCES customer(customer_id) ON DELETE RESTRICT CHECK (length(trim(customer_id)) > 0),
  device_id text NOT NULL CHECK (length(trim(device_id)) > 0),
  device_type text NOT NULL CHECK (device_type IN ('mobile', 'desktop', 'tablet')) CHECK (length(trim(device_type)) > 0),
  started_at timestamptz NOT NULL,
  ended_at timestamptz NOT NULL,
  CHECK (ended_at >= started_at),
  UNIQUE (session_id, customer_id)
);

CREATE TABLE cart (
  cart_id text PRIMARY KEY CHECK (cart_id ~ '^CART-2026-[0-9]{6,}$') CHECK (length(trim(cart_id)) > 0),
  customer_id text NOT NULL REFERENCES customer(customer_id) ON DELETE RESTRICT CHECK (length(trim(customer_id)) > 0),
  currency text NOT NULL CHECK (currency IN ('INR')) CHECK (length(trim(currency)) > 0),
  created_at timestamptz NOT NULL,
  UNIQUE (cart_id, customer_id)
);

CREATE TABLE cart_session (
  cart_session_id text PRIMARY KEY CHECK (cart_session_id ~ '^CS-[0-9]{6,}$') CHECK (length(trim(cart_session_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  session_id text NOT NULL REFERENCES session(session_id) ON DELETE RESTRICT CHECK (length(trim(session_id)) > 0),
  customer_id text NOT NULL REFERENCES customer(customer_id) ON DELETE RESTRICT CHECK (length(trim(customer_id)) > 0),
  linked_at timestamptz NOT NULL,
  UNIQUE (cart_id, session_id),
  FOREIGN KEY (cart_id, customer_id) REFERENCES cart(cart_id, customer_id),
  FOREIGN KEY (session_id, customer_id) REFERENCES session(session_id, customer_id)
);

CREATE TABLE cart_line (
  cart_line_id text PRIMARY KEY CHECK (cart_line_id ~ '^LINE-[0-9]{6,}$') CHECK (length(trim(cart_line_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  sku text NOT NULL CHECK (length(trim(sku)) > 0),
  created_at timestamptz NOT NULL,
  UNIQUE (cart_id, sku),
  UNIQUE (cart_line_id, cart_id)
);

CREATE TABLE cart_line_event (
  line_event_id text PRIMARY KEY CHECK (line_event_id ~ '^LE-[0-9]{6,}$') CHECK (length(trim(line_event_id)) > 0),
  cart_line_id text NOT NULL REFERENCES cart_line(cart_line_id) ON DELETE RESTRICT CHECK (length(trim(cart_line_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  revision bigint NOT NULL CHECK (revision >= 1),
  quantity bigint NOT NULL CHECK (quantity >= 0),
  unit_price_minor bigint NOT NULL CHECK (unit_price_minor >= 0),
  occurred_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL,
  UNIQUE (cart_line_id, revision),
  FOREIGN KEY (cart_line_id, cart_id) REFERENCES cart_line(cart_line_id, cart_id)
);

CREATE TABLE cart_event (
  cart_event_id text PRIMARY KEY CHECK (cart_event_id ~ '^CE-[0-9]{6,}$') CHECK (length(trim(cart_event_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  event_type text NOT NULL CHECK (event_type IN ('created', 'updated', 'checkout_started', 'abandoned', 'purchased', 'reopened', 'expired')) CHECK (length(trim(event_type)) > 0),
  revision bigint NOT NULL CHECK (revision >= 1),
  total_minor bigint NOT NULL CHECK (total_minor >= 0),
  occurred_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL,
  source_event_key text NOT NULL UNIQUE CHECK (length(trim(source_event_key)) > 0),
  UNIQUE (cart_id, revision)
);

CREATE TABLE campaign (
  campaign_id text PRIMARY KEY CHECK (campaign_id ~ '^CMP-2026-[0-9]{6,}$') CHECK (length(trim(campaign_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  customer_id text NOT NULL REFERENCES customer(customer_id) ON DELETE RESTRICT CHECK (length(trim(customer_id)) > 0),
  episode bigint NOT NULL CHECK (episode >= 1),
  variant text NOT NULL CHECK (variant IN ('A', 'B')) CHECK (length(trim(variant)) > 0),
  created_at timestamptz NOT NULL,
  policy_version text NOT NULL CHECK (length(trim(policy_version)) > 0),
  UNIQUE (cart_id, episode),
  UNIQUE (campaign_id, cart_id),
  FOREIGN KEY (cart_id, customer_id) REFERENCES cart(cart_id, customer_id)
);

CREATE TABLE message_template (
  template_id text PRIMARY KEY CHECK (template_id ~ '^MSG-CART-2026-[0-9]{6,}-[0-9]{2,}$') CHECK (length(trim(template_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  channel text NOT NULL CHECK (channel IN ('email', 'sms')) CHECK (length(trim(channel)) > 0),
  variant text NOT NULL CHECK (variant IN ('A', 'B')) CHECK (length(trim(variant)) > 0),
  version bigint NOT NULL CHECK (version >= 1),
  subject text CHECK (length(trim(subject)) > 0),
  body text NOT NULL CHECK (length(trim(body)) > 0),
  created_at timestamptz NOT NULL,
  UNIQUE (template_id, cart_id),
  CHECK ((channel = 'email' AND subject IS NOT NULL) OR (channel = 'sms' AND subject IS NULL))
);

CREATE TABLE campaign_message (
  dispatch_id text PRIMARY KEY CHECK (dispatch_id ~ '^DSP-2026-[0-9]{6,}$') CHECK (length(trim(dispatch_id)) > 0),
  campaign_id text NOT NULL REFERENCES campaign(campaign_id) ON DELETE RESTRICT CHECK (length(trim(campaign_id)) > 0),
  template_id text NOT NULL REFERENCES message_template(template_id) ON DELETE RESTRICT CHECK (length(trim(template_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  touch_number bigint NOT NULL CHECK (touch_number >= 1),
  due_at timestamptz NOT NULL,
  idempotency_key text NOT NULL UNIQUE CHECK (length(trim(idempotency_key)) > 0),
  UNIQUE (campaign_id, touch_number),
  FOREIGN KEY (campaign_id, cart_id) REFERENCES campaign(campaign_id, cart_id),
  FOREIGN KEY (template_id, cart_id) REFERENCES message_template(template_id, cart_id)
);

CREATE TABLE campaign_event (
  campaign_event_id text PRIMARY KEY CHECK (campaign_event_id ~ '^CME-[0-9]{6,}$') CHECK (length(trim(campaign_event_id)) > 0),
  campaign_id text NOT NULL REFERENCES campaign(campaign_id) ON DELETE RESTRICT CHECK (length(trim(campaign_id)) > 0),
  state text NOT NULL CHECK (state IN ('scheduled', 'running', 'suppressed', 'completed', 'cancelled')) CHECK (length(trim(state)) > 0),
  occurred_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL,
  reason_code text NOT NULL CHECK (length(trim(reason_code)) > 0)
);

CREATE TABLE send_attempt (
  send_id text PRIMARY KEY CHECK (send_id ~ '^SEND-2026-[0-9]{6,}$') CHECK (length(trim(send_id)) > 0),
  dispatch_id text NOT NULL REFERENCES campaign_message(dispatch_id) ON DELETE RESTRICT CHECK (length(trim(dispatch_id)) > 0),
  attempt_number bigint NOT NULL CHECK (attempt_number >= 1),
  attempted_at timestamptz NOT NULL,
  policy_version text NOT NULL CHECK (length(trim(policy_version)) > 0),
  UNIQUE (dispatch_id, attempt_number),
  UNIQUE (send_id, dispatch_id)
);

CREATE TABLE send_acceptance (
  dispatch_id text PRIMARY KEY REFERENCES campaign_message(dispatch_id) ON DELETE RESTRICT CHECK (length(trim(dispatch_id)) > 0),
  send_id text NOT NULL UNIQUE REFERENCES send_attempt(send_id) ON DELETE RESTRICT CHECK (length(trim(send_id)) > 0),
  provider_message_id text NOT NULL UNIQUE CHECK (length(trim(provider_message_id)) > 0),
  accepted_at timestamptz NOT NULL,
  FOREIGN KEY (send_id, dispatch_id) REFERENCES send_attempt(send_id, dispatch_id)
);

CREATE TABLE send_event (
  send_event_id text PRIMARY KEY CHECK (send_event_id ~ '^SE-[0-9]{6,}$') CHECK (length(trim(send_event_id)) > 0),
  send_id text NOT NULL REFERENCES send_attempt(send_id) ON DELETE RESTRICT CHECK (length(trim(send_id)) > 0),
  event_type text NOT NULL CHECK (event_type IN ('submitted', 'delivered', 'opened', 'clicked', 'failed', 'suppressed', 'unknown')) CHECK (length(trim(event_type)) > 0),
  occurred_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL,
  provider_event_id text UNIQUE CHECK (length(trim(provider_event_id)) > 0),
  reason_code text CHECK (length(trim(reason_code)) > 0),
  UNIQUE (send_event_id, send_id),
  CHECK (event_type NOT IN ('failed', 'suppressed') OR reason_code IS NOT NULL)
);

CREATE TABLE recovery_order (
  order_id text PRIMARY KEY CHECK (order_id ~ '^ORD-2026-[0-9]{6,}$') CHECK (length(trim(order_id)) > 0),
  cart_id text NOT NULL UNIQUE REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  customer_id text NOT NULL REFERENCES customer(customer_id) ON DELETE RESTRICT CHECK (length(trim(customer_id)) > 0),
  ordered_at timestamptz NOT NULL,
  currency text NOT NULL CHECK (currency IN ('INR')) CHECK (length(trim(currency)) > 0),
  total_minor bigint NOT NULL CHECK (total_minor >= 0),
  FOREIGN KEY (cart_id, customer_id) REFERENCES cart(cart_id, customer_id)
);

CREATE TABLE order_line (
  order_line_id text PRIMARY KEY CHECK (order_line_id ~ '^OL-[0-9]{6,}$') CHECK (length(trim(order_line_id)) > 0),
  order_id text NOT NULL REFERENCES recovery_order(order_id) ON DELETE RESTRICT CHECK (length(trim(order_id)) > 0),
  cart_line_id text NOT NULL REFERENCES cart_line(cart_line_id) ON DELETE RESTRICT CHECK (length(trim(cart_line_id)) > 0),
  quantity bigint NOT NULL CHECK (quantity >= 1),
  unit_price_minor bigint NOT NULL CHECK (unit_price_minor >= 0),
  UNIQUE (order_id, cart_line_id)
);

CREATE TABLE order_event (
  order_event_id text PRIMARY KEY CHECK (order_event_id ~ '^OE-[0-9]{6,}$') CHECK (length(trim(order_event_id)) > 0),
  order_id text NOT NULL REFERENCES recovery_order(order_id) ON DELETE RESTRICT CHECK (length(trim(order_id)) > 0),
  event_type text NOT NULL CHECK (event_type IN ('paid', 'cancelled', 'refunded')) CHECK (length(trim(event_type)) > 0),
  amount_minor bigint NOT NULL CHECK (amount_minor >= 0),
  occurred_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL,
  source_event_key text NOT NULL UNIQUE CHECK (length(trim(source_event_key)) > 0)
);

CREATE TABLE attribution (
  attribution_id text PRIMARY KEY CHECK (attribution_id ~ '^ATR-2026-[0-9]{6,}$') CHECK (length(trim(attribution_id)) > 0),
  order_id text NOT NULL UNIQUE REFERENCES recovery_order(order_id) ON DELETE RESTRICT CHECK (length(trim(order_id)) > 0),
  send_id text NOT NULL REFERENCES send_acceptance(send_id) ON DELETE RESTRICT CHECK (length(trim(send_id)) > 0),
  click_event_id text NOT NULL REFERENCES send_event(send_event_id) ON DELETE RESTRICT CHECK (length(trim(click_event_id)) > 0),
  model text NOT NULL CHECK (model IN ('last_click_7d_same_cart_v1')) CHECK (length(trim(model)) > 0),
  revenue_minor bigint NOT NULL CHECK (revenue_minor >= 0),
  decided_at timestamptz NOT NULL,
  policy_version text NOT NULL CHECK (length(trim(policy_version)) > 0),
  FOREIGN KEY (click_event_id, send_id) REFERENCES send_event(send_event_id, send_id)
);

CREATE TABLE decision_log (
  decision_id text PRIMARY KEY CHECK (decision_id ~ '^DEC-[0-9]{6,}$') CHECK (length(trim(decision_id)) > 0),
  cart_id text NOT NULL REFERENCES cart(cart_id) ON DELETE RESTRICT CHECK (length(trim(cart_id)) > 0),
  dispatch_id text REFERENCES campaign_message(dispatch_id) ON DELETE RESTRICT CHECK (length(trim(dispatch_id)) > 0),
  decision_type text NOT NULL CHECK (decision_type IN ('abandonment', 'enrollment', 'dispatch', 'attribution')) CHECK (length(trim(decision_type)) > 0),
  result text NOT NULL CHECK (result IN ('eligible', 'suppressed', 'deferred', 'attributed', 'organic', 'rejected')) CHECK (length(trim(result)) > 0),
  reason_codes jsonb NOT NULL,
  input_refs jsonb NOT NULL,
  policy_version text NOT NULL CHECK (length(trim(policy_version)) > 0),
  correlation_id text NOT NULL CHECK (length(trim(correlation_id)) > 0),
  decided_at timestamptz NOT NULL,
  CHECK (jsonb_typeof(reason_codes) = 'array'),
  CHECK (jsonb_typeof(input_refs) = 'object')
);

CREATE TABLE contact_block_event (
  block_event_id text PRIMARY KEY CHECK (block_event_id ~ '^BLOCK-[0-9]{6,}$') CHECK (length(trim(block_event_id)) > 0),
  customer_id text NOT NULL REFERENCES customer(customer_id) ON DELETE RESTRICT CHECK (length(trim(customer_id)) > 0),
  channel text NOT NULL CHECK (channel IN ('email', 'sms')) CHECK (length(trim(channel)) > 0),
  state text NOT NULL CHECK (state IN ('blocked', 'cleared')) CHECK (length(trim(state)) > 0),
  reason text NOT NULL CHECK (reason IN ('hard_bounce', 'complaint', 'invalid_address', 'manual', 'resolved')) CHECK (length(trim(reason)) > 0),
  effective_at timestamptz NOT NULL,
  recorded_at timestamptz NOT NULL
);

CREATE TABLE outbox_job (
  job_id text PRIMARY KEY CHECK (job_id ~ '^JOB-[0-9]{6,}$') CHECK (length(trim(job_id)) > 0),
  dispatch_id text NOT NULL UNIQUE REFERENCES campaign_message(dispatch_id) ON DELETE RESTRICT CHECK (length(trim(dispatch_id)) > 0),
  state text NOT NULL CHECK (state IN ('pending', 'leased', 'retry', 'done', 'cancelled', 'dead')) CHECK (length(trim(state)) > 0),
  available_at timestamptz NOT NULL,
  lease_until timestamptz,
  attempt_count bigint NOT NULL CHECK (attempt_count >= 0),
  last_error text CHECK (length(trim(last_error)) > 0),
  CHECK (state <> 'leased' OR lease_until IS NOT NULL)
);

CREATE TABLE outbox_event (
  outbox_event_id text PRIMARY KEY CHECK (outbox_event_id ~ '^JOBE-[0-9]{6,}$') CHECK (length(trim(outbox_event_id)) > 0),
  job_id text NOT NULL REFERENCES outbox_job(job_id) ON DELETE RESTRICT CHECK (length(trim(job_id)) > 0),
  state text NOT NULL CHECK (state IN ('pending', 'leased', 'retry', 'done', 'cancelled', 'dead')) CHECK (length(trim(state)) > 0),
  occurred_at timestamptz NOT NULL,
  reason_code text NOT NULL CHECK (length(trim(reason_code)) > 0)
);

CREATE INDEX consent_effective_idx ON consent(customer_id, channel, effective_at DESC, recorded_at);

CREATE INDEX cart_customer_idx ON cart(customer_id);

CREATE INDEX cart_event_time_idx ON cart_event(cart_id, occurred_at DESC, revision DESC);

CREATE INDEX line_event_time_idx ON cart_line_event(cart_id, occurred_at DESC);

CREATE INDEX send_event_time_idx ON send_event(send_id, event_type, occurred_at);

CREATE INDEX acceptance_time_idx ON send_acceptance(accepted_at);

CREATE INDEX campaign_customer_idx ON campaign(customer_id, cart_id);

CREATE INDEX order_customer_time_idx ON recovery_order(customer_id, ordered_at);

CREATE INDEX outbox_due_idx ON outbox_job(available_at) WHERE state IN ('pending', 'retry');

CREATE INDEX decision_cart_idx ON decision_log(cart_id, decided_at);

CREATE FUNCTION reject_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'append-only relation: %', TG_TABLE_NAME;
END;
$$;

CREATE TRIGGER dataset_run_immutable BEFORE UPDATE OR DELETE ON dataset_run FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER customer_immutable BEFORE UPDATE OR DELETE ON customer FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER consent_immutable BEFORE UPDATE OR DELETE ON consent FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER session_immutable BEFORE UPDATE OR DELETE ON session FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER cart_immutable BEFORE UPDATE OR DELETE ON cart FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER cart_session_immutable BEFORE UPDATE OR DELETE ON cart_session FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER cart_line_immutable BEFORE UPDATE OR DELETE ON cart_line FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER cart_line_event_immutable BEFORE UPDATE OR DELETE ON cart_line_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER cart_event_immutable BEFORE UPDATE OR DELETE ON cart_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER campaign_immutable BEFORE UPDATE OR DELETE ON campaign FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER message_template_immutable BEFORE UPDATE OR DELETE ON message_template FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER campaign_message_immutable BEFORE UPDATE OR DELETE ON campaign_message FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER campaign_event_immutable BEFORE UPDATE OR DELETE ON campaign_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER send_attempt_immutable BEFORE UPDATE OR DELETE ON send_attempt FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER send_acceptance_immutable BEFORE UPDATE OR DELETE ON send_acceptance FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER send_event_immutable BEFORE UPDATE OR DELETE ON send_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER recovery_order_immutable BEFORE UPDATE OR DELETE ON recovery_order FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER order_line_immutable BEFORE UPDATE OR DELETE ON order_line FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER order_event_immutable BEFORE UPDATE OR DELETE ON order_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER attribution_immutable BEFORE UPDATE OR DELETE ON attribution FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER decision_log_immutable BEFORE UPDATE OR DELETE ON decision_log FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER contact_block_event_immutable BEFORE UPDATE OR DELETE ON contact_block_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

CREATE TRIGGER outbox_event_immutable BEFORE UPDATE OR DELETE ON outbox_event FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();

COMMIT;
